package com.opentv.app.ui;
import android.view.*;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.opentv.app.R;import java.util.*;
public class CategoryAdapter extends RecyclerView.Adapter<CategoryAdapter.Holder>{public interface Listener{void onSelect(String c);}private final List<String>items=new ArrayList<>();private final Listener listener;private int selected=0;public CategoryAdapter(Listener l){listener=l;}public void setItems(List<String>v){items.clear();items.addAll(v);selected=0;notifyDataSetChanged();}
@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_category,p,false));}public void onBindViewHolder(@NonNull Holder h,int p){String v=items.get(p);h.text.setText(v);h.text.setSelected(p==selected);h.text.setOnClickListener(x->{int old=selected;selected=h.getBindingAdapterPosition();if(old>=0)notifyItemChanged(old);if(selected>=0)notifyItemChanged(selected);listener.onSelect(v);});}public int getItemCount(){return items.size();}static class Holder extends RecyclerView.ViewHolder{final TextView text;Holder(View v){super(v);text=v.findViewById(R.id.categoryText);}}}
